<?php
// Load shared helpers and restrict scheduling access to reception and doctors.
require_once __DIR__.'/../app/bootstrap.php'; require_once __DIR__.'/../app/layout.php'; require_role(['Receptionist','Doctor']);
// Receptionists create appointments and optionally assign a doctor.
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_role(['Receptionist']);verify_csrf();$pid=(int)($_POST['patient_id']??0);$doctor=(int)($_POST['doctor_id']??0);$when=$_POST['appointment_at']??'';$reason=trim($_POST['reason']??'');
 if(!$pid||$when==='')flash('error','Choose a patient and appointment date/time.');
 else {try{$dt=new DateTime($when);if($dt<new DateTime('-5 minutes'))throw new Exception();$s=db()->prepare("INSERT INTO appointments(patient_id,doctor_id,appointment_at,reason,created_by) VALUES(?,?,?,?,?)");$s->execute([$pid,$doctor?:null,$dt->format('Y-m-d H:i:s'),$reason?:null,current_user()['id']]);$appointmentId=(int)db()->lastInsertId();if($doctor){$cid=db()->prepare("INSERT INTO consultations(patient_id,appointment_id,doctor_id,status) VALUES(?,?,?,'Waiting')");$cid->execute([$pid,$appointmentId,$doctor]);}audit('appointment_created','appointment',$appointmentId);flash('success',$doctor?'Appointment scheduled and added to the doctor\'s queue.':'Appointment scheduled. Assign a doctor to add it to a consultation queue.');}catch(Throwable $e){flash('error','Appointment could not be saved. Check the selected details.');}}
 redirect('appointments.php');
}
// Load patients, available doctors, and recent appointments for the page.
$patients=db()->query('SELECT id,patient_number,full_name FROM patients ORDER BY full_name')->fetchAll();$doctors=db()->query("SELECT id,full_name FROM users WHERE role='Doctor' AND is_active=1 AND is_verified=1 ORDER BY full_name")->fetchAll();
$rows=db()->query('SELECT a.*,p.full_name AS patient_name,p.patient_number,u.full_name AS doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id LEFT JOIN users u ON u.id=a.doctor_id ORDER BY a.appointment_at DESC LIMIT 200')->fetchAll();
page_start('Appointments','appointments.php');
?>
<div class="section-heading"><div><h2>Appointment schedule</h2><p class="muted">Plan visits and assign a doctor.</p></div></div>
<?php if(in_array(current_user()['role'],['Admin','Receptionist'],true)): ?><div class="panel"><h3>Schedule appointment</h3><?php if(!$patients): ?><p class="muted">Register a patient before scheduling an appointment.</p><?php else: ?><form method="post" class="form-grid" data-track-changes><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Patient<select name="patient_id" required><option value="">Choose patient...</option><?php foreach($patients as $p): ?><option value="<?=(int)$p['id']?>"><?=e($p['patient_number'].' — '.$p['full_name'])?></option><?php endforeach; ?></select></label><label>Doctor (optional)<select name="doctor_id"><option value="">Assign later</option><?php foreach($doctors as $d): ?><option value="<?=(int)$d['id']?>"><?=e($d['full_name'])?></option><?php endforeach; ?></select></label><label>Date and time<input type="datetime-local" name="appointment_at" required></label><label>Reason for visit<input name="reason" maxlength="255"></label><div class="form-action"><button class="btn primary">Schedule appointment</button></div></form><?php endif; ?></div><?php endif; ?>
<div class="panel"><h3>Appointments</h3><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Date & time</th><th>Doctor</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['patient_number'].' · '.$r['patient_name'])?></td><td><?=e(date('d M Y, H:i',strtotime($r['appointment_at'])))?></td><td><?=e($r['doctor_name']??'Not assigned')?></td><td><?=e($r['reason']??'—')?></td><td><span class="status"><?=e($r['status'])?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">No appointments yet.</td></tr><?php endif; ?></tbody></table></div></div>
<?php page_end(); ?>
